import numpy as np
S=np.load('skel.npy')
H,W=S.shape
nb=np.zeros_like(S,dtype=int)
for dx in(-1,0,1):
    for dy in(-1,0,1):
        if dx==0 and dy==0: continue
        nb+=np.roll(np.roll(S,dx,0),dy,1)
nb=nb*S
pts=set(map(tuple,np.argwhere(S==1)))  # (row,col)
nodes=[p for p in pts if nb[p]!=2]
# cluster nodes
nodeset=set(nodes)
clusters=[]
seen=set()
for p in nodes:
    if p in seen: continue
    stack=[p]; comp=[]
    while stack:
        c=stack.pop()
        if c in seen: continue
        seen.add(c); comp.append(c)
        for dx in range(-2,3):
            for dy in range(-2,3):
                q=(c[0]+dx,c[1]+dy)
                if q in nodeset and q not in seen: stack.append(q)
    clusters.append(comp)
centers=[(sum(c[0] for c in comp)/len(comp), sum(c[1] for c in comp)/len(comp)) for comp in clusters]
cid={}
for i,comp in enumerate(clusters):
    for c in comp: cid[c]=i
print(len(clusters))
for i,c in enumerate(centers):
    print(i, 'x=%.0f y=%.0f'%(c[1],c[0]), len(clusters[i]))
# trace edges: BFS on skeleton from each cluster
import collections
edges=collections.Counter()
visited=set()
for i,comp in enumerate(clusters):
    for c in comp:
        for dx in(-1,0,1):
            for dy in(-1,0,1):
                q=(c[0]+dx,c[1]+dy)
                if q in pts and q not in cid:
                    # walk
                    prev=c; cur=q; path=[c,q]
                    while True:
                        nxt=None
                        for ex in(-1,0,1):
                            for ey in(-1,0,1):
                                r=(cur[0]+ex,cur[1]+ey)
                                if r==cur or r==prev: continue
                                if r in pts and r not in path[-3:]:
                                    if r in cid:
                                        nxt=r; break
                                    nxt=r
                            if nxt and nxt in cid: break
                        if nxt is None: break
                        path.append(nxt)
                        if nxt in cid: break
                        prev=cur; cur=nxt
                    if path[-1] in cid:
                        j=cid[path[-1]]
                        if i!=j:
                            key=tuple(sorted((i,j)))
                            edges[key]=max(edges[key],len(path))
print('edges')
for (a,b),L in sorted(edges.items()):
    print(a,b,'len',L, 'x=%.0f,y=%.0f'%(centers[a][1],centers[a][0]),'->','x=%.0f,y=%.0f'%(centers[b][1],centers[b][0]))
